messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Straight Duel — Red vs Blue</title>
<style>
  :root{
    --ink:#17150f; --paper:#f7f2e6; --red:#d81e2c; --blue:#0f5bd8;
    --disp:Futura,'Century Gothic','Avenir Next','Trebuchet MS',sans-serif;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{height:100%;overflow:hidden}
  body{background:#eed4a8;color:var(--ink);font-family:var(--disp);user-select:none;-webkit-user-select:none}
  canvas{display:block}

  #hud{position:fixed;inset:0;pointer-events:none;z-index:5}
  #tower{position:absolute;top:18px;left:18px;min-width:238px;padding:10px 13px 12px;
    background:rgba(250,246,236,.82);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
    border:1px solid rgba(23,21,15,.16);border-radius:12px;box-shadow:0 10px 30px rgba(23,21,15,.12)}
  .runRow{display:flex;justify-content:space-between;font-size:10px;font-weight:700;letter-spacing:.16em;opacity:.6;margin:1px 1px 8px}
  .carRow{display:flex;align-items:center;gap:8px;padding:6px 2px 5px;border-top:1px solid rgba(23,21,15,.12);
    font-variant-numeric:tabular-nums;transition:opacity .3s}
  .carRow.trail{opacity:.6}
  .pos{font-weight:800;font-size:15px;width:13px}
  .chip{width:11px;height:11px;border-radius:3px;background:var(--c);box-shadow:inset 0 0 0 1px rgba(23,21,15,.28)}
  .name{font-weight:800;font-size:12px;letter-spacing:.14em;flex:1}
  .speed{font-weight:800;font-size:16px}
  .unit{font-size:9px;font-weight:700;letter-spacing:.1em;opacity:.55}
  .gapRow{display:flex;align-items:center;gap:9px;padding:8px 2px 2px}
  .gapTrack{flex:1;height:3px;border-radius:2px;background:rgba(23,21,15,.14);overflow:hidden;display:block}
  #gapBar{display:block;height:100%;width:100%;background:var(--ink);transform-origin:left center;transform:scaleX(0)}
  #gapTxt{font-size:10px;font-weight:800;letter-spacing:.06em;min-width:96px;text-align:right;font-variant-numeric:tabular-nums}

  #num{position:absolute;left:50%;top:40%;transform:translate(-50%,-50%);font-weight:800;
    font-size:clamp(70px,13vw,140px);letter-spacing:.03em;color:var(--paper);white-space:nowrap;
    text-shadow:0 3px 0 rgba(23,21,15,.3),0 14px 40px rgba(23,21,15,.28);opacity:0}
  #num.show{animation:pop .85s cubic-bezier(.2,.75,.25,1) forwards}
  #num.long{animation-duration:1.5s}
  #num.go{color:#4ee07f}
  @keyframes pop{
    0%{opacity:0;transform:translate(-50%,-50%) scale(1.7)}
    14%{opacity:1;transform:translate(-50%,-50%) scale(1)}
    72%{opacity:1;transform:translate(-50%,-50%) scale(1)}
    100%{opacity:0;transform:translate(-50%,-50%) scale(.94)}}

  #cap{position:absolute;left:50%;bottom:16px;transform:translateX(-50%);font-size:10px;font-weight:700;
    letter-spacing:.24em;opacity:.55;white-space:nowrap}
  #vig{position:fixed;inset:0;pointer-events:none;z-index:4;
    background:radial-gradient(120% 95% at 50% 42%,rgba(0,0,0,0) 60%,rgba(23,18,10,.15) 100%)}
  #flash{position:fixed;inset:0;pointer-events:none;z-index:6;background:#fff8ea;opacity:0}
  #flash.on{animation:fl .55s ease-out forwards}
  @keyframes fl{0%{opacity:.7}100%{opacity:0}}
  #fade{position:fixed;inset:0;pointer-events:none;z-index:7;background:#f2dfba;opacity:0;transition:opacity .45s ease}
  #fade.on{opacity:1}
  @media (max-width:640px){
    #cap{font-size:8px;letter-spacing:.16em}
    #tower{min-width:200px;padding:8px 10px}
  }
</style>
</head>
<body>
<div id="hud">
  <div id="tower">
    <div class="runRow"><span id="runLabel">RUN 01</span><span id="stateLabel">LIGHTS</span></div>
    <div class="carRow" id="rowRed"><span class="pos" id="posRed">1</span><span class="chip" style="--c:#d81e2c"></span><span class="name">RED</span><span class="speed" id="spdRed">0</span><span class="unit">KM/H</span></div>
    <div class="gapRow"><span class="gapTrack"><span id="gapBar"></span></span><span id="gapTxt">STAGING</span></div>
    <div class="carRow" id="rowBlue"><span class="pos" id="posBlue">2</span><span class="chip" style="--c:#0f5bd8"></span><span class="name">BLUE</span><span class="speed" id="spdBlue">0</span><span class="unit">KM/H</span></div>
  </div>
  <div id="num"></div>
  <div id="cap">232 M STRAIGHT &middot; RED VS BLUE &middot; ENDLESS REMATCH</div>
</div>
<div id="vig"></div>
<div id="flash"></div>
<div id="fade"></div>

<script type="module">
import * as THREE from './three.module.js';

/* ---------- tiny math helpers ---------- */
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const sstep=(a,b,x)=>{const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t);};
const smoother=t=>{t=clamp(t,0,1);return t*t*t*(t*(t*6-15)+10);};
const rnd=(a,b)=>a+Math.random()*(b-a);

/* ---------- the race script (deterministic story) ----------
   BLUE: killer launch, ~180 km/h, slight tyre fade near the end.
   RED : slower launch, then a hard mid-race boost to ~228 km/h.
   Story: blue leads early, red surges, overtake just past half
   distance (~t=5.3s at ~134m), red takes the flag ~0.9s ahead. */
const V_BLUE=t=>30*(1-Math.exp(-t/0.85))*(1-0.08*sstep(6,8.5,t));
const V_RED =t=>Math.max(26*(1-Math.exp(-t)),38*(1-Math.exp(-Math.max(t-2,0)/0.8)));
const KMH=6;

const SCALE=1.35, START_X=-2.8, FINISH_X=232, FINISH_C=FINISH_X-3.3;
const LANE_R=-3.5, LANE_B=3.5, WHEEL_R=0.42*SCALE;
const CD_GO=3.2, CD_MARKS=[0.8,1.6,2.4];

/* ---------- renderer / scene / camera ---------- */
const renderer=new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.toneMapping=THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure=1.05;
renderer.outputColorSpace=THREE.SRGBColorSpace;
document.body.appendChild(renderer.domElement);

const scene=new THREE.Scene();
scene.background=new THREE.Color(0xf6dfb4);
scene.fog=new THREE.Fog(0xf6dfb4,70,560);
const camera=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,0.1,2000);

/* ---------- lights ---------- */
const SUN_DIR=new THREE.Vector3(0.55,0.42,-0.5).normalize();
const sun=new THREE.DirectionalLight(0xfff0d6,3.0);
sun.castShadow=true;
sun.shadow.mapSize.set(2048,2048);
Object.assign(sun.shadow.camera,{left:-48,right:48,top:48,bottom:-48,near:20,far:340});
sun.shadow.camera.updateProjectionMatrix();
sun.shadow.bias=-0.0004; sun.shadow.normalBias=0.03;
scene.add(sun,sun.target);
scene.add(new THREE.HemisphereLight(0xcfdadb,0x9a7c55,0.9));
const fill=new THREE.DirectionalLight(0xe8ecef,0.75);
fill.position.set(6,10,18); scene.add(fill);

/* ---------- sky dome (gradient + low sun, matches fog) ---------- */
const sky=new THREE.Mesh(new THREE.SphereGeometry(900,48,24),new THREE.ShaderMaterial({
  side:THREE.BackSide, depthWrite:false, fog:false,
  uniforms:{cTop:{value:new THREE.Color(0x7fa0b0)},cHor:{value:new THREE.Color(0xf6dfb4)},
            cSun:{value:new THREE.Color(0xffe6bb)},uSun:{value:SUN_DIR.clone()}},
  vertexShader:'varying vec3 vW;void main(){vec4 w=modelMatrix*vec4(position,1.0);vW=w.xyz;gl_Position=projectionMatrix*viewMatrix*w;}',
  fragmentShader:[
    'varying vec3 vW;uniform vec3 cTop,cHor,cSun,uSun;',
    'void main(){vec3 d=normalize(vW);float h=clamp(d.y,0.0,1.0);',
    ' vec3 col=mix(cHor,cTop,pow(h,0.58));',
    ' float s=max(dot(d,normalize(uSun)),0.0);',
    ' col+=cSun*(pow(s,900.0)*1.2+pow(s,20.0)*0.16+pow(s,3.0)*0.05);',
    ' col=mix(col,cHor*0.985,smoothstep(0.0,0.15,-d.y));',
    ' gl_FragColor=vec4(col,1.0);}'].join('\n')
}));
scene.add(sky);

/* ---------- canvas-generated textures (no external assets) ---------- */
function canvasTex(w,h,draw){
  const c=document.createElement('canvas');c.width=w;c.height=h;
  draw(c.getContext('2d'),w,h);
  const t=new THREE.CanvasTexture(c);
  t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=8;return t;
}
const groundTex=canvasTex(256,256,(g,w,h)=>{
  g.fillStyle='#cdb287';g.fillRect(0,0,w,h);
  for(let i=0;i<26;i++){g.fillStyle=Math.random()<.5?'rgba(120,96,60,0.06)':'rgba(236,220,180,0.06)';
    g.beginPath();g.ellipse(Math.random()*w,Math.random()*h,rnd(14,50),rnd(8,30),Math.random()*3.14,0,6.29);g.fill();}
  for(let i=0;i<2200;i++){const s=rnd(70,120)|0;
    g.fillStyle='rgba('+s+','+(s-14)+','+(s-40)+','+rnd(0.15,0.5).toFixed(2)+')';
    g.fillRect(Math.random()*w,Math.random()*h,rnd(1,2.2),rnd(1,2.2));}
});
groundTex.wrapS=groundTex.wrapT=THREE.RepeatWrapping;groundTex.repeat.set(90,90);

const roadTex=canvasTex(256,256,(g,w,h)=>{
  g.fillStyle='#3b3835';g.fillRect(0,0,w,h);
  for(let i=0;i<2400;i++){const s=rnd(38,86)|0;
    g.fillStyle='rgba('+s+','+(s-2)+','+(s-6)+','+rnd(0.2,0.55).toFixed(2)+')';
    g.fillRect(Math.random()*w,Math.random()*h,rnd(1,2),rnd(1,2));}
  for(const v of[0.189,0.311,0.689,0.811]){const y=(1-v)*h;      // tyre wear bands
    for(const[bw,a]of[[46,0.05],[28,0.07],[14,0.09]]){g.fillStyle='rgba(12,10,8,'+a+')';g.fillRect(0,y-bw/2,w,bw);}}
  for(let i=0;i<40;i++){g.fillStyle='rgba(220,214,200,0.05)';g.fillRect(Math.random()*w,Math.random()*h,rnd(6,30),1);}
});
roadTex.wrapS=THREE.RepeatWrapping;roadTex.wrapT=THREE.ClampToEdgeWrapping;roadTex.repeat.set(48,1);

function checkerTex(cols,rows){return canvasTex(cols*36,rows*36,(g,w,h)=>{
  const s=w/cols;
  for(let i=0;i<cols;i++)for(let j=0;j<rows;j++){
    g.fillStyle=(i+j)%2?'#17150f':'#f7f2e6';g.fillRect(i*s,j*s,s+1,s+1);}});}
const checkStrip=checkerTex(14,2), checkBeam=checkerTex(24,2);

const signTex=canvasTex(1024,176,(g,w,h)=>{
  g.fillStyle='#f7f2e6';g.fillRect(0,0,w,h);
  g.strokeStyle='#17150f';g.lineWidth=10;g.strokeRect(5,5,w-10,h-10);
  const s=22;
  for(let i=0;i<4;i++)for(let j=0;j<8;j++){
    g.fillStyle=(i+j)%2?'#17150f':'#f7f2e6';
    g.fillRect(18+j*s,18+i*s,s,s);g.fillRect(w-18-(j+1)*s,18+i*s,s,s);}
  g.fillStyle='#17150f';g.font='800 96px Futura,"Century Gothic","Trebuchet MS",sans-serif';
  g.textAlign='center';g.textBaseline='middle';g.fillText('FINISH',w/2,h/2+4);
});
function boardTex(txt){return canvasTex(256,96,(g,w,h)=>{
  g.fillStyle='#f7f2e6';g.fillRect(0,0,w,h);
  g.strokeStyle='#17150f';g.lineWidth=6;g.strokeRect(3,3,w-6,h-6);
  g.fillStyle='#17150f';g.font='800 46px Futura,"Century Gothic","Trebuchet MS",sans-serif';
  g.textAlign='center';g.textBaseline='middle';g.fillText(txt,w/2,h/2+2);});}
function roundelTex(num){return canvasTex(128,128,(g,w,h)=>{
  g.clearRect(0,0,w,h);
  g.fillStyle='#f7f2e6';g.beginPath();g.arc(64,64,54,0,6.29);g.fill();
  g.lineWidth=7;g.strokeStyle='#17150f';g.beginPath();g.arc(64,64,50,0,6.29);g.stroke();
  g.fillStyle='#17150f';g.font='800 52px Futura,"Century Gothic","Trebuchet MS",sans-serif';
  g.textAlign='center';g.textBaseline='middle';g.fillText(num,64,66);});}

/* ---------- world: ground, drag strip, furniture ---------- */
const world=new THREE.Group();scene.add(world);

const ground=new THREE.Mesh(new THREE.PlaneGeometry(2400,2400),
  new THREE.MeshStandardMaterial({map:groundTex,roughness:1}));
ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;world.add(ground);

const road=new THREE.Mesh(new THREE.PlaneGeometry(320,14),
  new THREE.MeshStandardMaterial({map:roadTex,roughness:.96}));
road.rotation.x=-Math.PI/2;road.position.set(140,0.02,0);road.receiveShadow=true;world.add(road);

const shGeo=new THREE.PlaneGeometry(322,1.5);shGeo.rotateX(-Math.PI/2);
const shMat=new THREE.MeshStandardMaterial({color:0xb59a72,roughness:1});
for(const z of[-7.75,7.75]){const m=new THREE.Mesh(shGeo,shMat);m.position.set(140,0.03,z);m.receiveShadow=true;world.add(m);}

const lineGeo=new THREE.PlaneGeometry(322,0.16);lineGeo.rotateX(-Math.PI/2);
const lineMat=new THREE.MeshStandardMaterial({color:0xf2ead6,roughness:1});
for(const z of[-6.7,6.7]){const m=new THREE.Mesh(lineGeo,lineMat);m.position.set(140,0.05,z);m.receiveShadow=true;world.add(m);}

{ // dashed centre line (one instanced mesh)
  const geo=new THREE.PlaneGeometry(2.6,0.16);geo.rotateX(-Math.PI/2);
  const im=new THREE.InstancedMesh(geo,lineMat,39);
  const M=new THREE.Matrix4();let k=0;
  for(let x=-6;x<=222;x+=6){M.setPosition(x,0.055,0);im.setMatrixAt(k++,M);}
  im.instanceMatrix.needsUpdate=true;im.receiveShadow=true;world.add(im);
}

const stripMat=new THREE.MeshStandardMaterial({map:checkStrip,roughness:.9});
const startStrip=new THREE.Mesh(new THREE.PlaneGeometry(14,1.2),stripMat);
startStrip.rotation.x=-Math.PI/2;startStrip.position.set(0,0.06,0);startStrip.receiveShadow=true;world.add(startStrip);
const finStrip=new THREE.Mesh(new THREE.PlaneGeometry(14,1.6),stripMat);
finStrip.rotation.x=-Math.PI/2;finStrip.position.set(FINISH_X,0.06,0);finStrip.receiveShadow=true;world.add(finStrip);

/* finish gantry */
const ivoryMat=new THREE.MeshStandardMaterial({color:0xe9e2d0,roughness:.8});
const pylonGeo=new THREE.BoxGeometry(0.55,7.4,0.55);
for(const z of[-8.3,8.3]){const p=new THREE.Mesh(pylonGeo,ivoryMat);p.position.set(FINISH_X,3.7,z);p.castShadow=true;world.add(p);}
const beamCheckMat=new THREE.MeshStandardMaterial({map:checkBeam,roughness:.85,emissive:0xf7f2e6,emissiveIntensity:0});
const beam=new THREE.Mesh(new THREE.BoxGeometry(17.6,1.5,0.5),
  [ivoryMat,ivoryMat,ivoryMat,ivoryMat,beamCheckMat,beamCheckMat]);
beam.position.set(FINISH_X,7.6,0);beam.castShadow=true;world.add(beam);
for(const x of[FINISH_X-3.9,FINISH_X+3.9]){const s=new THREE.Mesh(new THREE.BoxGeometry(0.07,1.0,0.07),ivoryMat);
  s.position.set(x,8.9,0.22);world.add(s);}
const sign=new THREE.Mesh(new THREE.PlaneGeometry(9,1.55),
  new THREE.MeshStandardMaterial({map:signTex,roughness:.9}));
sign.position.set(FINISH_X,9.2,0.3);sign.castShadow=true;world.add(sign);

/* drag-race "christmas tree" */
const treeG=new THREE.Group();treeG.position.set(1.5,0,-8.6);world.add(treeG);
const poleMat=new THREE.MeshStandardMaterial({color:0x5c544a,roughness:.85});
const tPole=new THREE.Mesh(new THREE.CylinderGeometry(0.09,0.11,3.2,10),poleMat);
tPole.position.y=1.6;tPole.castShadow=true;treeG.add(tPole);
const tHead=new THREE.Mesh(new THREE.BoxGeometry(1.15,2.5,0.45),ivoryMat);
tHead.position.y=4.45;tHead.castShadow=true;treeG.add(tHead);
const tPlate=new THREE.Mesh(new THREE.PlaneGeometry(0.95,2.2),
  new THREE.MeshStandardMaterial({color:0x1d1a15,roughness:.9}));
tPlate.position.set(0,4.45,0.235);treeG.add(tPlate);
const lamps=[];
for(const[col,y]of[['#ffb03a',5.32],['#ffb03a',4.70],['#ffb03a',4.08],['#2ee56a',3.46]]){
  const m=new THREE.MeshStandardMaterial({color:0x241f18,emissive:new THREE.Color(col),emissiveIntensity:0,roughness:.4});
  const c=new THREE.Mesh(new THREE.CircleGeometry(0.28,24),m);c.position.set(0,y,0.245);treeG.add(c);lamps.push(m);
}
const treeLight=new THREE.PointLight(0x35e06b,0,34,2);
treeLight.position.set(1.5,3.4,-7.2);world.add(treeLight);

/* distance boards */
for(const d of[40,80,120,160,200]){
  const post=new THREE.Mesh(new THREE.CylinderGeometry(0.07,0.07,2.4,8),poleMat);
  post.position.set(d,1.2,-9.5);post.castShadow=true;world.add(post);
  const b=new THREE.Mesh(new THREE.PlaneGeometry(2.5,0.95),
    new THREE.MeshStandardMaterial({map:boardTex(d+' M'),roughness:.9}));
  b.position.set(d,2.55,-9.45);b.castShadow=true;world.add(b);
}
/* light poles for parallax */
for(let x=15;x<=255;x+=30){
  const g=new THREE.Group();g.position.set(x,0,-9.9);
  const p=new THREE.Mesh(new THREE.CylinderGeometry(0.09,0.12,6.6,8),poleMat);p.position.y=3.3;p.castShadow=true;g.add(p);
  const arm=new THREE.Mesh(new THREE.BoxGeometry(0.1,0.1,1.6),poleMat);arm.position.set(0,6.4,0.8);g.add(arm);
  const lamp=new THREE.Mesh(new THREE.BoxGeometry(0.24,0.12,0.5),
    new THREE.MeshStandardMaterial({color:0x35322c,roughness:.7}));lamp.position.set(0,6.34,1.5);g.add(lamp);
  world.add(g);
}
/* horizon mounds + scattered rocks */
const hillCols=[0xb19a72,0xa89066,0x9aa08a,0xb7a37c];
function addHill(x,z,r,sy,c){
  const m=new THREE.Mesh(new THREE.SphereGeometry(r,24,14),new THREE.MeshStandardMaterial({color:c,roughness:1}));
  m.scale.set(1,sy,0.85);m.position.set(x,-r*sy*0.28,z);world.add(m);
}
for(const[x,z,r,sy,ci]of[[-160,-190,110,.20,0],[-40,-240,150,.16,1],[90,-205,120,.19,2],[210,-235,160,.15,3],
  [330,-195,115,.20,1],[465,-250,170,.14,2],[-235,-150,95,.20,0],[300,205,140,.16,3],
  [60,235,120,.18,1],[-130,195,105,.20,2],[520,215,135,.15,0]])addHill(x,z,r,sy,hillCols[ci]);
const rockGeo=new THREE.DodecahedronGeometry(1,0);
const rockCols=[0x8f7c5e,0x7d6c52,0x9a8a6a];
for(let i=0;i<12;i++){
  const m=new THREE.Mesh(rockGeo,new THREE.MeshStandardMaterial({color:rockCols[i%3],roughness:1,flatShading:true}));
  m.position.set(rnd(-30,285),rnd(0.1,0.4),(Math.random()<.6?-1:1)*rnd(11,52));
  m.scale.set(rnd(0.4,1.5),rnd(0.3,0.9),rnd(0.4,1.4));m.rotation.y=Math.random()*6.3;
  m.castShadow=true;m.receiveShadow=true;world.add(m);
}

/* ---------- cars (extruded silhouette, real differentiators) ---------- */
function shapeFrom(pts){const s=new THREE.Shape();s.moveTo(pts[0][0],pts[0][1]);
  for(let i=1;i<pts.length;i++)s.lineTo(pts[i][0],pts[i][1]);s.closePath();return s;}
const lowerPts=[[-2.35,0.30],[2.05,0.30],[2.38,0.44],[2.30,0.72],[1.35,0.86],[-1.55,0.88],[-2.28,0.74]];
const cabinPts=[[-1.30,0.86],[1.18,0.86],[0.52,1.46],[-0.52,1.44]];
function extrudeGeo(pts,depth,bt,bs){
  const g=new THREE.ExtrudeGeometry(shapeFrom(pts),
    {depth,bevelEnabled:true,bevelThickness:bt,bevelSize:bs,bevelSegments:2,steps:1,curveSegments:4});
  g.translate(0,0,-depth/2);return g;
}
const tireGeo=new THREE.CylinderGeometry(0.42,0.42,0.30,22);
const hubGeo=new THREE.CylinderGeometry(0.235,0.235,0.34,18);
const ringGeo=new THREE.TorusGeometry(0.185,0.022,8,28);
const tireMat=new THREE.MeshStandardMaterial({color:0x141417,roughness:.85});
const hubMat=new THREE.MeshStandardMaterial({color:0xd3d6da,metalness:.75,roughness:.3});
const rimRingMat=new THREE.MeshStandardMaterial({color:0xf4efe2,roughness:.5});
function makeWheel(){
  const w=new THREE.Group();
  const t=new THREE.Mesh(tireGeo,tireMat);t.rotation.x=Math.PI/2;t.castShadow=true;w.add(t);
